define('xwiki-pro-commons-quick-action-overwrite', {
  prefix: 'xwiki.pro.commons.quick.actions.',
  keys: [
    'defaultContent'
  ]
});

define('xwiki-macro-quick-action', ['deferred!ckeditor', 'jquery', 'xwiki-l10n!xwiki-pro-commons-quick-action-overwrite'], function (ckeditorPromise, $, l10n) {
  const requestPageRef = XWiki.Model.resolve('XWikiProCommons.CKEPlugins.getMacroDescriptor', XWiki.EntityType.DOCUMENT);
  const baseURL = new XWiki.Document(requestPageRef).getURL('get');

  // Cache descriptor by macroId+language so we only fetch once
  const descriptorCache = {};

  function fetchDescriptor(macroId, language) {
    const cacheKey = `${macroId}::${language}`;
    if (!descriptorCache[cacheKey]) {
      const url = `${baseURL}?macroID=${encodeURIComponent(macroId)}&language=${encodeURIComponent(language)}`;
      descriptorCache[cacheKey] = $.getJSON(url);
    }
    return descriptorCache[cacheKey];
  }

  function registerMacroQuickAction(macroId, options = {}) {
    const {
      language = $('html').attr('lang'),
      macroName = macroId,
      group = 'content',
      defaultContent = l10n['defaultContent'],
      xwikiCommand = 'xwiki-macro-insert',
      icon = 'fa fa-cubes',
      parameters = {}
    } = options;

    const descriptorPromise = fetchDescriptor(macroId, language);

    ckeditorPromise.done(function (ckeditor) {
      ckeditor.on('instanceCreated', function (event) {
        event.editor.once('configLoaded', function (event) {
          const editor = event.editor;

          descriptorPromise.done(function (response) {
            const existing = editor.config.extraQuickActions || [];
            editor.config.extraQuickActions = existing.concat([{
              id: `macro-${macroId}`,
              name: response.name,
              description: response.description,
              iconClass: icon,
              command: {
                name: xwikiCommand,
                data: {
                  name: macroName,
                  content: defaultContent,
                  parameters
                }
              }
            }]);
          }).fail(function (jqxhr, textStatus, error) {
            console.error(`[quick-action][${macroId}] Request failed: ${textStatus}, ${error}`);
          });
        });
      });
    });
  }

  return {
    registerMacroQuickAction
  };
});
